  p_bmLong = L31_bmLong;
  p_bmRough = L31_bmRough;
  p_bmMetal = L31_bmMetal;
  p_bmRelief = L31_bmRelief;
  p_bmMirror = L31_bmMirror;
  p_bmSky = L31_bmSky;
  p_bmWall = L31_bmWall;
  p_bmFloor = L31_bmFloor;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec2 bmG = dot(s3, s3) > 0.25 ? normalize(s3) : vec2(1.0, 0.0);
    // along the brushing, across it
    vec2 bmQ = vec2(dot(uv, bmG), dot(uv, vec2(-bmG.y, bmG.x)));
    // the scratches: noise stretched far along the brushing, one row a scratch, faded to its mean where a scratch is
    // under a pixel; a few deeper, longer ones over them
    float bmFine = mix(0.5, kn(vec2(bmQ.x * p_bmLong * 4.0, bmQ.y * p_bmLines) + seed), kfade(2.0 / p_bmLines));
    float bmDeep = mix(0.5, kn(vec2(bmQ.x * p_bmLong, bmQ.y * p_bmLines * 0.18) + seed + 17.0), kfade(8.0 / p_bmLines));
    float bmS = 0.75 * bmFine + 0.25 * smoothstep(0.35, 0.8, bmDeep);
    // a slow cloud of the belt's passes, so a big sheet isn't one flat grey
    float bmPass = kfbm4(vec2(bmQ.x * 0.6, bmQ.y * 7.0) + seed * 1.3);
    vec3 bmC = p_bmColour * (1.0 + p_bmStreak * (bmS - 0.5) * 0.9) * (0.94 + 0.12 * bmPass);
    k.colour = bmC;
    k.metal = p_bmMetal;
    k.rough = clamp(p_bmRough + 0.12 * (bmS - 0.5) + 0.05 * (bmPass - 0.5), 0.03, 1.0);
    k.height = p_bmRelief * (bmS - 0.5);
    // the room mirrored, smeared along the brushing: its ray tipped across the scratches by each one's slope
    vec3 bmV = normalize(wp - cameraPosition);
    vec3 bmN = normalize(wn);
    vec3 bmR = reflect(bmV, bmN);
    float bmCos = clamp(dot(-bmV, bmN), 0.0, 1.0);
    float bmFres = 0.7 + 0.3 * pow(1.0 - bmCos, 3.0);
    vec3 bmRoom = rmRoom(normalize(bmR + 0.08 * (bmS - 0.5) * vec3(1.0, 0.0, 1.0)), clamp(p_bmRough * 2.2, 0.0, 1.0), p_bmSky, p_bmWall, p_bmFloor);
    k.glow = p_bmMirror * bmRoom * bmC * bmFres * (0.85 + 0.3 * bmS);
    if (lookView > 0.5 && lookView < 1.5) k.colour = vec3(0.5 + 0.5 * bmG.x, 0.5 + 0.5 * bmG.y, 0.5);

}

void look_32(inout Look k) {
  p_rbColour = L32_rbColour;
  p_rbBloom = L32_rbBloom;
  p_rbBloomAmount = L32_rbBloomAmount;
  p_rbGrit = L32_rbGrit;
  p_rbRelief = L32_rbRelief;
  p_rbRough = L32_rbRough;
  p_rbSheen = L32_rbSheen;
  p_rbSheenRough = L32_rbSheenRough;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float rbG = kn(uv * p_rbGrit + seed) * kfade(2.0 / p_rbGrit);
    float rbP = 1.0 - smoothstep(0.0, 0.25, kcell(uv * p_rbGrit * 0.25 + seed)) ;
    rbP *= kfade(6.0 / p_rbGrit);
    float rbB = smoothstep(0.35, 0.8, kfbm4(uv * 4.0 + seed)) * p_rbBloomAmount;
    k.colour = mix(p_rbColour, p_rbBloom, rbB) * (0.95 + 0.1 * rbG) * (1.0 - 0.3 * rbP);
    k.rough = clamp(p_rbRough + 0.08 * rbB + 0.05 * rbG, 0.0, 1.0);
    k.height = p_rbRelief * (rbG - 0.6 * rbP);
    k.sheen = p_rbSheen;
    k.sheenRough = p_rbSheenRough;

}

void look_33(inout Look k) {
  p_bhColour = L33_bhColour;
  p_bhGap = L33_bhGap;
  p_bhBands = L33_bhBands;
  p_bhWires = L33_bhWires;
  p_bhRelief = L33_bhRelief;
  p_bhRough = L33_bhRough;
  p_bhMetal = L33_bhMetal;
  p_bhGrime = L33_bhGrime;
  p_bhGrimeColour = L33_bhGrimeColour;
  p_bhMirror = L33_bhMirror;
  p_bhSky = L33_bhSky;
  p_bhWall = L33_bhWall;
  p_bhFloor = L33_bhFloor;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the two helices: coordinates along each band's way, a band every 1/bhBands across it
    vec2 bhP = uv * p_bhBands;
    float bhA = bhP.x + bhP.y;
    float bhB = bhP.x - bhP.y;
    // a twill: band A over the other in two cells of four along its way, then under two
    float bhOver = 1.0 - step(1.5, mod(floor(bhB) - floor(bhA), 4.0));
    // across each band: its wires' crowns, and the band's own edges falling into the gap
    float bhFa = fract(bhA);
    float bhFb = fract(bhB);
    float bhWa = 0.5 + 0.5 * cos(6.2832 * bhFa * p_bhWires);
    float bhWb = 0.5 + 0.5 * cos(6.2832 * bhFb * p_bhWires);
    float bhEa = smoothstep(0.0, 0.08, bhFa) * (1.0 - smoothstep(0.92, 1.0, bhFa));
    float bhEb = smoothstep(0.0, 0.08, bhFb) * (1.0 - smoothstep(0.92, 1.0, bhFb));
    // the band on top here: its wires' crown, rising over the band beneath and dropping at the crossing's ends
    float bhLiftA = sin(3.1416 * fract(bhB));
    float bhLiftB = sin(3.1416 * fract(bhA));
    float bhTop = mix(bhEb * (0.55 + 0.45 * bhWb) * (0.6 + 0.4 * bhLiftB), bhEa * (0.55 + 0.45 * bhWa) * (0.6 + 0.4 * bhLiftA), bhOver);
    // fade the weave to its mean where a band is finer than a pixel, and the wires where they are
    float bhSeenBand = kfade(2.0 / p_bhBands);
    float bhH = mix(0.62, bhTop, bhSeenBand);
    float bhGr = p_bhGrime * smoothstep(0.35, 0.8, kfbm4(uv * 5.0 + seed + 3.0));
    vec3 bhC = mix(p_bhGap, p_bhColour, smoothstep(0.08, 0.6, bhH));
    bhC = mix(bhC, p_bhGrimeColour, bhGr * (0.4 + 0.6 * (1.0 - bhH)));
    k.colour = bhC;
    k.metal = p_bhMetal * smoothstep(0.05, 0.5, bhH) * (1.0 - 0.6 * bhGr);
    k.rough = clamp(p_bhRough + 0.3 * (1.0 - bhH) + 0.3 * bhGr, 0.05, 1.0);
    k.height = p_bhRelief * bhH;
    k.ao = 1.0 - 0.5 * (1.0 - bhH) * bhSeenBand;
    vec3 bhV = normalize(wp - cameraPosition);
    vec3 bhN = normalize(wn);
    vec3 bhRoom = rmRoom(reflect(bhV, bhN), clamp(p_bhRough * 1.8, 0.0, 1.0), p_bhSky, p_bhWall, p_bhFloor);
    k.glow = p_bhMirror * bhRoom * bhC * smoothstep(0.2, 0.8, bhH) * (1.0 - bhGr);

}

void look_34(inout Look k) {
  p_rdColour = L34_rdColour;
  p_rdTubeColour = L34_rdTubeColour;
  p_rdGap = L34_rdGap;
  p_rdEdge = L34_rdEdge;
  p_rdPitch = L34_rdPitch;
  p_rdTube = L34_rdTube;
  p_rdFins = L34_rdFins;
  p_rdDepth = L34_rdDepth;
  p_rdRough = L34_rdRough;
  p_rdMetal = L34_rdMetal;
  p_rdDust = L34_rdDust;
  p_rdDustColour = L34_rdDustColour;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec2 rdW = dot(s3, s3) > 0.25 ? normalize(s3) : vec2(1.0, 0.0);
    // along the tubes, across them
    vec2 rdQ = vec2(dot(uv, rdW), dot(uv, vec2(-rdW.y, rdW.x)));
    // the rows: a tube's flat face, then the fin's band, a row every pitch across the tubes
    float rdRow = fract(rdQ.y / p_rdPitch);
    float rdT = smoothstep(0.0, 0.04, rdRow) * (1.0 - smoothstep(p_rdTube, p_rdTube + 0.04, rdRow));
    float rdRowsSeen = kfade(p_rdPitch * 1.5);
    rdT = mix(p_rdTube, rdT, rdRowsSeen);
    // the fin's folds along the tubes: each fold's edge a bright thin line, the gap between two folds dark and deep
    float rdFold = fract(rdQ.x * p_rdFins);
    float rdEdge = 1.0 - smoothstep(0.0, 0.22, abs(rdFold - 0.5) * 2.0 - 0.55);
    float rdFoldsSeen = kfade(2.0 / p_rdFins);
    rdEdge = mix(0.4, rdEdge, rdFoldsSeen);
    float rdFin = 1.0 - rdT;
    vec3 rdC = mix(p_rdGap, p_rdColour * p_rdEdge, rdEdge);
    rdC = mix(rdC, p_rdTubeColour, rdT);
    float rdD = p_rdDust * smoothstep(0.45, 0.85, kfbm4(uv * 5.0 + seed + 2.0) + 0.15 * kn(uv * 80.0 + seed));
    rdC = mix(rdC, p_rdDustColour * (0.7 + 0.5 * rdEdge), rdD * rdFin);
    k.colour = rdC;
    k.metal = p_rdMetal * (0.5 + 0.5 * rdT);
    k.rough = clamp(p_rdRough + 0.25 * rdFin * (1.0 - rdEdge) + 0.3 * rdD * rdFin, 0.05, 1.0);
    k.height = -p_rdDepth * rdFin * (1.0 - 0.6 * rdEdge);
    k.ao = 1.0 - 0.7 * rdFin * (1.0 - rdEdge) * rdFoldsSeen;
    k.aoDirect = 0.6;

}

void look_35(inout Look k) {
  p_plColour = L35_plColour;
  p_plStipple = L35_plStipple;
  p_plRelief = L35_plRelief;
  p_plRough = L35_plRough;
  p_plRoughVar = L35_plRoughVar;
  p_plTone = L35_plTone;
  p_plThrough = L35_plThrough;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float plS = kn(uv * p_plStipple + seed) * kfade(2.0 / p_plStipple);
    float plS2 = kn(uv * p_plStipple * 0.37 + seed + 9.0) * kfade(5.0 / p_plStipple);
    float plW = kfbm4(uv * 3.0 + seed);
    k.colour = p_plColour * (1.0 + p_plTone * (plW - 0.5) * 2.0);
    k.rough = clamp(p_plRough + p_plRoughVar * (plW - 0.5) * 2.0 + 0.05 * plS, 0.0, 1.0);
    k.height = p_plRelief * (0.6 * plS + 0.4 * plS2);
    if (p_plThrough > 0.0) {
      float plFace = clamp(abs(dot(normalize(cameraPosition - wp), normalize(wn))), 0.0, 1.0);
      k.glow = p_plThrough * k.colour * (0.45 + 0.55 * plFace) * (0.9 + 0.2 * plW);
    }

}

void look_36(inout Look k) {
  p_tpColour = L36_tpColour;
  p_tpFaded = L36_tpFaded;
  p_tpFade = L36_tpFade;
  p_tpGrain = L36_tpGrain;
  p_tpGrainDepth = L36_tpGrainDepth;
  p_tpRough = L36_tpRough;
  p_tpDust = L36_tpDust;
  p_tpDustColour = L36_tpDustColour;
  p_tpDustHeight = L36_tpDustHeight;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float tpSee = kfade(2.0 / p_tpGrain);
    float tpId, tpEdge;
    kvor(uv * p_tpGrain + seed, tpId, tpEdge);
    float tpRim = (1.0 - smoothstep(0.0, 0.18, tpEdge)) * tpSee;
    float tpCell = (kh1(tpId) - 0.5) * tpSee;
    float tpUp = smoothstep(0.2, 0.9, wn.y);
    float tpF = p_tpFade * tpUp * (0.7 + 0.3 * kfbm4(uv * 3.0 + seed));
    k.colour = mix(p_tpColour, p_tpFaded, tpF) * (1.0 + 0.12 * tpCell - 0.15 * tpRim);
    k.rough = clamp(p_tpRough + 0.1 * tpF - 0.08 * tpRim, 0.0, 1.0);
    k.height = p_tpGrainDepth * (0.6 * tpRim + 0.4 * tpCell);
    float tpLow = 1.0 - smoothstep(0.0, p_tpDustHeight, wp.y);
    float tpD = clamp(p_tpDust * tpLow * smoothstep(0.3, 0.8, kfbm(uv * 5.0 + seed + 7.0) + 0.3 * tpLow) * 1.4, 0.0, 1.0);
    k.colour = mix(k.colour, p_tpDustColour, tpD);
    k.rough = mix(k.rough, 0.9, tpD);

}

void look_37(inout Look k) {
  p_pmColour = L37_pmColour;
  p_pmPeel = L37_pmPeel;
  p_pmRelief = L37_pmRelief;
  p_pmRough = L37_pmRough;
  p_pmCoat = L37_pmCoat;
  p_pmCoatRough = L37_pmCoatRough;
  p_pmOil = L37_pmOil;
  p_pmOilColour = L37_pmOilColour;
  p_pmOilStreaks = L37_pmOilStreaks;
  p_pmOilRough = L37_pmOilRough;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float pmF = kfade(2.0 / p_pmPeel);
    float pmPeel = (1.0 - kcell(uv * p_pmPeel + seed)) * pmF;
    float pmFine = kn(uv * p_pmPeel * 2.7 + seed + 3.0) * kfade(1.0 / p_pmPeel);
    k.colour = p_pmColour * (0.985 + 0.03 * kfbm4(uv * 2.0 + seed));
    k.rough = clamp(p_pmRough + 0.04 * pmFine, 0.0, 1.0);
    k.height = p_pmRelief * (0.75 * pmPeel + 0.25 * pmFine);
    k.clearcoat = p_pmCoat;
    k.clearcoatRough = p_pmCoatRough;
    if (p_pmOil > 0.0) {
      // runs: noise drawn out along u, fine across v; blotches: a slow fbm; thick where both lie
      float pmRun = kn(vec2(uv.x * p_pmOilStreaks * 0.12, uv.y * p_pmOilStreaks) + seed + 5.0);
      float pmBlot = kfbm(uv * 2.5 + seed + 9.0);
      float pmThick = smoothstep(0.4, 0.8, 0.55 * pmRun + 0.45 * pmBlot);
      float pmO = clamp(p_pmOil * (0.15 + 0.85 * pmThick), 0.0, 1.0);
      vec3 pmOilC = p_pmOilColour * (0.7 + 0.6 * kn(vec2(uv.x * 3.0, uv.y * 40.0) + seed));
      k.colour = mix(k.colour, pmOilC, pmO);
      k.rough = mix(k.rough, p_pmOilRough + 0.5 * (1.0 - pmThick), pmO);
      k.clearcoat = mix(k.clearcoat, 0.0, pmO);
      k.height += p_pmOil * 0.00006 * pmThick;
    }

}

void look_38(inout Look k) {
  p_gvColour = L38_gvColour;
  p_gvSpangle = L38_gvSpangle;
  p_gvTone = L38_gvTone;
  p_gvRough = L38_gvRough;
  p_gvRoughVar = L38_gvRoughVar;
  p_gvBloom = L38_gvBloom;
  p_gvMetal = L38_gvMetal;
  p_gvRelief = L38_gvRelief;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float gvId, gvE;
    vec2 gvP = uv * p_gvSpangle + seed * 11.0;
    gvP += vec2(kn(uv * 9.0 + seed), kn(uv * 9.0 + seed + 4.0)) * 0.6;
    kvor(gvP, gvId, gvE);
    float gvF = kfade(1.5 / p_gvSpangle);
    // the dendrites: fine lines along the crystal's own angle
    float gvA = gvId * 6.2832;
    vec2 gvDir = vec2(cos(gvA), sin(gvA));
    float gvDen = abs(sin(dot(uv, gvDir) * p_gvSpangle * 40.0 + kn(uv * p_gvSpangle * 6.0) * 3.0));
    gvDen = smoothstep(0.6, 1.0, gvDen) * kfade(0.8 / (p_gvSpangle * 12.0)) * gvF;
    float gvB = smoothstep(0.45, 0.8, kfbm4(uv * 2.5 + seed + 2.0)) * p_gvBloom;
    float gvT = (gvId - 0.5) * 2.0 * p_gvTone * gvF;
    vec3 c = p_gvColour * (1.0 + gvT) * (1.0 - 0.06 * gvDen);
    c = mix(c, vec3(0.56, 0.56, 0.55), gvB);
    k.colour = c;
    k.metal = mix(p_gvMetal, 0.3, gvB);
    k.rough = clamp(p_gvRough + p_gvRoughVar * (kh1(gvId * 17.0) - 0.5) * 2.0 * gvF + 0.08 * gvDen + 0.3 * gvB, 0.05, 1.0);
    k.height = p_gvRelief * (smoothstep(0.03, 0.0, gvE) * gvF + 0.5 * gvDen);

}

void look_39(inout Look k) {
  p_wcKind = L39_wcKind;
  p_wcColour = L39_wcColour;
  p_wcColour2 = L39_wcColour2;
  p_wcColour3 = L39_wcColour3;
  p_wcRepeat = L39_wcRepeat;
  p_wcLine = L39_wcLine;
  p_wcThread = L39_wcThread;
  p_wcFleck = L39_wcFleck;
  p_wcRelief = L39_wcRelief;
  p_wcSheen = L39_wcSheen;
  p_wcRough = L39_wcRough;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the cloth's own way: x across the stripes, y along them
    vec2 wcG = dot(s3, s3) > 0.25 ? normalize(s3) : vec2(0.0, 1.0);
    vec2 wcUv = vec2(dot(uv, vec2(wcG.y, -wcG.x)), dot(uv, wcG));
    // the twill ground: floats two over and one under, stepping a thread each row, diagonal ribs across it
    vec2 q = wcUv / p_wcThread;
    float row = floor(q.y);
    float over = step(0.34, fract((q.x + row) / 3.0));
    float tw = abs(sin(fract(q.y) * 3.14159)) * mix(0.6, 1.0, over);
    float twF = kfade(p_wcThread * 0.5);
    float h = mix(0.5, tw, twF);
    // the pattern woven through it
    vec3 col = p_wcColour;
    float rep = p_wcRepeat;
    if (p_wcKind < 0.5) {
      // a stripe is drawn while a pixel is no wider than it, its edges softened over the pixel; seen from farther
      // off it is its share of the cloth's colour
      float s = wcBand(wcUv.x, rep, p_wcLine);
      float sMean = p_wcLine / rep;
      s = mix(sMean, s, kfade(p_wcLine * 2.0));
      col = mix(col, p_wcColour2, s);
    } else {
      // two wide bands and one thin line each way in each repeat
      float bu = wcBand(wcUv.x, rep, p_wcLine) + wcBand(wcUv.x + rep * 0.5, rep, p_wcLine * 0.6);
      float bv = wcBand(wcUv.y, rep, p_wcLine) + wcBand(wcUv.y + rep * 0.5, rep, p_wcLine * 0.6);
      float lu = wcBand(wcUv.x + rep * 0.25, rep, p_wcLine * 0.18);
      float lv = wcBand(wcUv.y + rep * 0.25, rep, p_wcLine * 0.18);
      float f = kfade(p_wcLine * 1.2);
      bu = mix(p_wcLine * 1.6 / rep, min(bu, 1.0), f);
      bv = mix(p_wcLine * 1.6 / rep, min(bv, 1.0), f);
      // a band's yarn is the warp's or the weft's, so where only one runs the twill shows half of it
      col = mix(col, p_wcColour2, 0.5 * (bu + bv));
      col = mix(col, p_wcColour3, 0.55 * max(lu, lv) * f);
    }
    // heather: fibres a shade off in the yarn, finer than a thread
    float fleck = smoothstep(0.55, 0.85, kn(uv / (p_wcThread * 0.7) + seed * 3.0));
    col *= 1.0 + p_wcFleck * (mix(0.18, fleck, kfade(p_wcThread * 0.7)) - 0.18) * 1.6;
    col *= 0.94 + 0.1 * kfbm4(uv * 4.0 + seed);
    col *= 0.8 + 0.28 * h;
    k.colour = col;
    k.rough = p_wcRough;
    k.height = p_wcRelief * h;
    k.ao = mix(0.8, 1.0, h);
    k.sheen = mix(col, vec3(1.0), 0.35) * p_wcSheen;
    k.sheenRough = 0.65;

}

void look_40(inout Look k) {
  p_upKind = L40_upKind;
  p_upColour = L40_upColour;
  p_upColour2 = L40_upColour2;
  p_upThread = L40_upThread;
  p_upFleck = L40_upFleck;
  p_upPrint = L40_upPrint;
  p_upMotif = L40_upMotif;
  p_upRelief = L40_upRelief;
  p_upSheen = L40_upSheen;
  p_upRough = L40_upRough;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // a loop's or a thread's own detail (its ring, its crossing) is half of it across: faded out before it aliases
    float upF = kfade(p_upThread * 0.5);
    vec2 cl = upCloth(uv, p_upKind, p_upThread, seed);
    float h = mix(0.5, cl.x, upF);
    float lite = mix(0.5, cl.y, upF);
    // heather: fibres of the second colour twisted into the yarn, finer than a thread
    float fleck = smoothstep(0.55, 0.85, kn(uv / (p_upThread * 0.7) + seed * 3.0));
    float fleckMean = 0.18;
