  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec2 cmP, cmHalf;
    float cmPage;
    if (s2.x > 0.001 && s2.y > 0.001) {
      cmHalf = s2.xy * 0.5;
      cmP = s3 / cmHalf.y;
      cmPage = floor(s2.z + 0.5);
    } else {
      vec2 cmSize = vec2(p_cmCell * 1.75, p_cmCell);
      cmHalf = cmSize * 0.5;
      cmP = (fract(uv / cmSize) - 0.5) * 2.0 * vec2(1.75, 1.0);
      cmPage = 0.0;
    }
    if (cmPage > 3.5 || cmPage < -0.5) cmPage = 0.0;
    float cmA = cmHalf.x / cmHalf.y;
    float cmE = fwidth(cmP.y) * 0.9 + 0.002;
    float cmWhite = 0.0, cmAmber = 0.0, cmRedInk = 0.0;
    // the title strip across the top, its page's name in bars
    float cmTitleOn = step(0.72, cmP.y) * step(cmPage, 1.5);
    cmWhite = max(cmWhite, cmWord(cmP, -cmA + 0.1, 0.86, 4.0 + cmPage, 0.11, cmE) * cmTitleOn);
    // the screen's own window (the backlight's edge darkening a little at the rim)
    if (cmPage < 0.5) {
      for (int i = 0; i < 3; i++) {
        float cmX = (float(i) - 1.0) * cmA * 0.64;
        vec2 cmQ = (cmP - vec2(cmX, -0.02)) / 0.5;
        float cmR = length(cmQ);
        float cmEr = cmE / 0.5;
        float cmAng = degrees(atan(cmQ.x, cmQ.y));
        float cmFrom = cmAng + 135.0;
        float cmIn = step(-0.5, cmFrom) * step(cmFrom, 270.5);
        float cmStep = 270.0 / 20.0;
        float cmK = cmFrom / cmStep;
        float cmD = abs(fract(cmK + 0.5) - 0.5) * cmStep * 0.0174533 * cmR;
        float cmLong = step(abs(fract(cmK / 4.0 + 0.5) - 0.5) * 4.0, 0.5);
        float cmR0 = mix(0.78, 0.66, cmLong);
        float cmTick = (1.0 - smoothstep(0.035, 0.035 + cmEr, cmD)) * smoothstep(cmR0 - cmEr, cmR0, cmR) * (1.0 - smoothstep(0.92, 0.92 + cmEr, cmR)) * cmIn;
        float cmHot = step(270.0 * 0.8, cmFrom);
        cmWhite = max(cmWhite, cmTick * (1.0 - cmHot));
        cmRedInk = max(cmRedInk, cmTick * cmHot);
        // the scale's ring inside its ticks
        cmWhite = max(cmWhite, cmLine(cmR - 0.62, 0.012, cmEr) * cmIn * 0.6);
        float cmRead = i == 0 ? p_cmRead1 : i == 1 ? p_cmRead2 : p_cmRead3;
        float cmAn = radians(-135.0 + 270.0 * cmRead);
        vec2 cmDir = vec2(sin(cmAn), cos(cmAn));
        float cmAlong = clamp(dot(cmQ, cmDir), 0.0, 0.86);
        float cmOff = length(cmQ - cmDir * cmAlong);
        cmAmber = max(cmAmber, 1.0 - smoothstep(0.035, 0.035 + cmEr, cmOff));
        cmAmber = max(cmAmber, 1.0 - smoothstep(0.09, 0.09 + cmEr, cmR));
        // its reading under it, its name over it
        cmWhite = max(cmWhite, cmNumber(cmP, vec2(cmX, -0.48), cmRead * (i == 0 ? 1.0 : i == 1 ? 120.0 : 100.0), 3, i == 0 ? 2 : 0, 0.16, cmE));
        cmWhite = max(cmWhite, cmWord(cmP, cmX - 0.17, 0.52, 3.0, 0.07, cmE));
      }
    } else if (cmPage < 1.5) {
      vec2 cmG = vec2(cmP.x / (cmA - 0.1), (cmP.y + 0.05) / 0.72);
      float cmIn = step(abs(cmG.x), 1.0) * step(abs(cmG.y), 1.0);
      float cmGrid = max(cmLine(fract(cmG.x * 4.0 + 0.5) - 0.5, 0.01, cmE * 2.0), cmLine(fract(cmG.y * 2.0 + 0.5) - 0.5, 0.01, cmE * 2.0));
      cmWhite = max(cmWhite, cmGrid * cmIn * 0.25);
      float cmT1 = 0.55 * sin(cmG.x * 7.0 + 1.3) * exp(-0.4 * abs(cmG.x + 0.2)) + 0.1;
      float cmT2 = clamp(0.6 * sin(cmG.x * 4.0 - 0.5), -0.7, 0.8);
      cmAmber = max(cmAmber, cmLine(cmG.y - cmT1, 0.02, cmE * 1.6) * cmIn);
      cmWhite = max(cmWhite, cmLine(cmG.y - cmT2, 0.015, cmE * 1.6) * cmIn);
      for (int i = 0; i < 3; i++) {
        cmWhite = max(cmWhite, cmNumber(cmP, vec2(-cmA + 0.12, 0.62 - float(i) * 0.6), 2.0 - float(i), 1, 0, 0.1, cmE));
      }
    } else if (cmPage < 2.5) {
      cmWhite = max(cmWhite, cmNumber(cmP, vec2(-0.25, -0.05), p_cmTemp, 3, 1, 0.7, cmE));
      cmWhite = max(cmWhite, cmLine(length(cmP - vec2(0.42, 0.22)) - 0.06, 0.018, cmE));
      for (int i = 0; i < 7; i++) {
        float x = 0.75 + float(i) * 0.1;
        float hgt = 0.12 + float(i) * 0.06;
        float lit = step(float(i) + 0.5, p_cmFan);
        float bar = cmBox(cmP, vec2(x, -0.5), vec2(x + 0.06, -0.5 + hgt), cmE);
        cmWhite = max(cmWhite, bar * mix(0.15, 1.0, lit));
      }
      cmAmber = max(cmAmber, cmBox(cmP, vec2(0.75, 0.3), vec2(1.2, 0.45), cmE));
    } else {
      cmAmber = max(cmAmber, cmWord(cmP, -cmA + 0.15, 0.35, 2.0, 0.16, cmE));
      cmWhite = max(cmWhite, cmNumber(cmP, vec2(0.0, -0.1), p_cmFreq, 4, 1, 0.66, cmE));
      vec2 cmBx = vec2(cmA - 0.32, -0.1);
      float cmFrame = cmBox(cmP, cmBx - 0.18, cmBx + 0.18, cmE) * (1.0 - cmBox(cmP, cmBx - 0.15, cmBx + 0.15, cmE));
      cmWhite = max(cmWhite, max(cmFrame, cmNumber(cmP, cmBx, 3.0, 1, 0, 0.22, cmE)));
    }
    // finer than a pixel, the figures fade to the page's mean glow: each page by its finest stroke (the meters' ticks, the
    // graph's traces, the big figures' segments), in the screen's half heights
    float cmStroke = cmPage < 0.5 ? 0.035 : cmPage < 1.5 ? 0.03 : 0.11;
    // the readouts (climate, radio) drawn harder: a darker ground, brighter figures
    bool cmReadout = cmPage > 1.5;
    float cmF = 1.0 - smoothstep(cmStroke * 0.6, cmStroke * 1.6, fwidth(cmP.y));
    cmWhite = clamp(cmWhite, 0.0, 1.0) * cmF;
    cmAmber = clamp(cmAmber, 0.0, 1.0) * cmF;
    cmRedInk = clamp(cmRedInk, 0.0, 1.0) * cmF;
    float cmMean = 0.035 * (1.0 - cmF);
    vec3 cmBack = mix(p_cmGround, p_cmTitle, cmTitleOn);
    // the backlight's edge: a little darker toward the rim
    float cmEdge = 1.0 - 0.35 * smoothstep(0.75, 1.0, max(abs(cmP.x) / cmA, abs(cmP.y)));
    if (cmReadout) {
      cmBack *= 0.45;
      cmWhite *= 1.6;
      cmAmber *= 1.4;
      cmMean *= 0.8;
    }
    vec3 cmLit = cmBack * cmEdge + p_cmInk * cmWhite + p_cmNeedle * cmAmber + p_cmRed * cmRedInk + p_cmInk * cmMean;
    k.colour = cmLit * 0.15;
    k.metal = 0.0;
    k.rough = p_cmRough;
    k.glow = p_cmGain * cmLit;
    k.clearcoat = 0.8;
    k.clearcoatRough = 0.05;

}

