  p_bmRough = L31_bmRough;
  p_bmMetal = L31_bmMetal;
  p_bmRelief = L31_bmRelief;
  p_bmMirror = L31_bmMirror;
  p_bmSky = L31_bmSky;
  p_bmWall = L31_bmWall;
  p_bmFloor = L31_bmFloor;
  vec2 uv = vLookUv;
