void look_39(inout Look k) {
  p_wcKind = L39_wcKind;
  p_wcColour = L39_wcColour;
  p_wcColour2 = L39_wcColour2;
  p_wcColour3 = L39_wcColour3;
  p_wcRepeat = L39_wcRepeat;
  p_wcLine = L39_wcLine;
  p_wcThread = L39_wcThread;
  p_wcFleck = L39_wcFleck;
  p_wcRelief = L39_wcRelief;
  p_wcSheen = L39_wcSheen;
  p_wcRough = L39_wcRough;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    // the cloth's own way: x across the stripes, y along them
    vec2 wcG = dot(s3, s3) > 0.25 ? normalize(s3) : vec2(0.0, 1.0);
    vec2 wcUv = vec2(dot(uv, vec2(wcG.y, -wcG.x)), dot(uv, wcG));
    // the twill ground: floats two over and one under, stepping a thread each row, diagonal ribs across it
    vec2 q = wcUv / p_wcThread;
    float row = floor(q.y);
    float over = step(0.34, fract((q.x + row) / 3.0));
    float tw = abs(sin(fract(q.y) * 3.14159)) * mix(0.6, 1.0, over);
    float twF = kfade(p_wcThread * 0.5);
    float h = mix(0.5, tw, twF);
    // the pattern woven through it
    vec3 col = p_wcColour;
    float rep = p_wcRepeat;
    if (p_wcKind < 0.5) {
      // a stripe is drawn while a pixel is no wider than it, its edges softened over the pixel; seen from farther
      // off it is its share of the cloth's colour
      float s = wcBand(wcUv.x, rep, p_wcLine);
      float sMean = p_wcLine / rep;
      s = mix(sMean, s, kfade(p_wcLine * 2.0));
      col = mix(col, p_wcColour2, s);
    } else {
      // two wide bands and one thin line each way in each repeat
      float bu = wcBand(wcUv.x, rep, p_wcLine) + wcBand(wcUv.x + rep * 0.5, rep, p_wcLine * 0.6);
      float bv = wcBand(wcUv.y, rep, p_wcLine) + wcBand(wcUv.y + rep * 0.5, rep, p_wcLine * 0.6);
      float lu = wcBand(wcUv.x + rep * 0.25, rep, p_wcLine * 0.18);
      float lv = wcBand(wcUv.y + rep * 0.25, rep, p_wcLine * 0.18);
      float f = kfade(p_wcLine * 1.2);
      bu = mix(p_wcLine * 1.6 / rep, min(bu, 1.0), f);
      bv = mix(p_wcLine * 1.6 / rep, min(bv, 1.0), f);
      // a band's yarn is the warp's or the weft's, so where only one runs the twill shows half of it
      col = mix(col, p_wcColour2, 0.5 * (bu + bv));
      col = mix(col, p_wcColour3, 0.55 * max(lu, lv) * f);
    }
    // heather: fibres a shade off in the yarn, finer than a thread
    float fleck = smoothstep(0.55, 0.85, kn(uv / (p_wcThread * 0.7) + seed * 3.0));
    col *= 1.0 + p_wcFleck * (mix(0.18, fleck, kfade(p_wcThread * 0.7)) - 0.18) * 1.6;
    col *= 0.94 + 0.1 * kfbm4(uv * 4.0 + seed);
    col *= 0.8 + 0.28 * h;
    k.colour = col;
    k.rough = p_wcRough;
    k.height = p_wcRelief * h;
    k.ao = mix(0.8, 1.0, h);
    k.sheen = mix(col, vec3(1.0), 0.35) * p_wcSheen;
    k.sheenRough = 0.65;

}

void look_40(inout Look k) {
