  vec3 wn = normalize(vLookWN);

    vec2 gfP;
    float gfRad, gfKind, gfReadAt;
    if (s2.x > 0.001) {
      gfRad = s2.x * 0.5;
      gfP = s3 / gfRad;
      gfKind = floor(s2.z + 0.5);
      gfReadAt = clamp(s2.w, 0.0, 1.0);
    } else {
      gfRad = p_gfRadius;
      gfP = uv / gfRad;
      gfKind = 0.0;
      gfReadAt = p_gfRead;
    }
    if (gfKind > 8.5 || gfKind < -0.5) gfKind = 0.0;
    if (gfKind > 2.5 && gfKind < 3.5) {
      // a warning lamp, unlit: its lens's colour by s2.w, deep and dark; the bulb behind it a faint brightening in its
      // middle; the frame's shadow round its square edge
      float gfWhich = floor(s2.w + 0.5);
      vec3 gfLens = gfWhich < 0.5 ? vec3(0.09, 0.006, 0.004) : gfWhich < 1.5 ? vec3(0.1, 0.045, 0.003) :
                    gfWhich < 2.5 ? vec3(0.008, 0.06, 0.012) : vec3(0.006, 0.02, 0.09);
      vec2 gfSq = abs(gfP);
      float gfEdge = max(gfSq.x, gfSq.y);
      float gfEw = fwidth(gfEdge) + 0.002;
      float gfBulb = 1.0 - smoothstep(0.0, 0.75, length(gfP));
      vec3 gfL = gfLens * (0.7 + 0.6 * gfBulb);
      gfL *= 1.0 - 0.6 * smoothstep(0.78 - gfEw, 0.95, gfEdge);
      k.colour = gfL;
      k.metal = 0.0;
      k.rough = 0.25;
      k.glow = vec3(0.0);
    } else {
    bool gfSmall = gfKind > 1.5;
    float gfR = length(gfP);
    float gfE = fwidth(gfR) * 0.75 + 0.002;
    // the angle from straight up, degrees, clockwise; the sweep is centred on straight up
    float gfA = degrees(atan(gfP.x, gfP.y));
    float gfSw = gfSmall ? 90.0 : p_gfSweep;
    float gfHalf = gfSw * 0.5;
    float gfFrom = gfA + gfHalf;
    float gfIn = step(-0.5, gfFrom) * step(gfFrom, gfSw + 0.5);
    float gfInk = 0.0;
    float gfRedInk = 0.0;
    float gfNumInk = 0.0;
    float gfNe = fwidth(gfP.x) + fwidth(gfP.y);
    bool gfNum = p_gfNumerals > 0.5;
    if (gfKind < 0.5) {
      float gfStep = gfSw / p_gfTicks;
      gfInk = gfIn * max(gfRing(gfFrom, gfStep, gfR, 0.8, 0.93, 0.012, gfE), gfRing(gfFrom, gfStep * 5.0, gfR, 0.68, 0.93, 0.024, gfE));
      if (gfNum) {
        float gfCount = floor(p_gfSpeedTop / p_gfSpeedStep + 0.5);
        for (int i = 0; i <= 40; i++) {
          if (float(i) > gfCount) break;
          float v = float(i) * p_gfSpeedStep;
          gfNumInk = max(gfNumInk, gfNumber(gfP, gfAt(gfSw * v / p_gfSpeedTop, gfSw, 0.52, vec2(0.0)), v, 0.11, gfNe));
        }
      }
    } else if (gfKind < 1.5) {
      // gfTachSteps steps of 500 rpm, long at each thousand; red from gfTachRed of the sweep, with a red arc inside
      // the marks
      float gfStep = gfSw / p_gfTachSteps;
      float gfMarks = gfIn * max(gfRing(gfFrom, gfStep, gfR, 0.8, 0.93, 0.014, gfE), gfRing(gfFrom, gfStep * 2.0, gfR, 0.68, 0.93, 0.026, gfE));
      float gfHot = step(gfSw * p_gfTachRed, gfFrom) * gfIn;
      float gfArc = gfHot * smoothstep(0.62 - gfE, 0.62, gfR) * (1.0 - smoothstep(0.68, 0.68 + gfE, gfR));
      gfInk = gfMarks * (1.0 - gfHot);
      gfRedInk = max(gfMarks * gfHot, gfArc);
      if (gfNum) {
        float gfTop = p_gfTachSteps * 0.5;
        for (int i = 0; i <= 12; i++) {
          if (float(i) > gfTop) break;
          gfNumInk = max(gfNumInk, gfNumber(gfP, gfAt(gfSw * float(i) / gfTop, gfSw, 0.48, vec2(0.0)), float(i), 0.15, gfNe));
        }
      }
    } else {
      // three long marks over the top arc, two short between; the low end's red
      float gfMarks = gfIn * max(gfRing(gfFrom, gfSw / 4.0, gfR, 0.72, 0.92, 0.03, gfE), gfRing(gfFrom, gfSw / 2.0, gfR, 0.56, 0.92, 0.05, gfE));
      float gfLow = step(gfFrom, gfSw * 0.12);
      gfInk = gfMarks * (1.0 - gfLow);
      gfRedInk = gfMarks * gfLow;
      if (gfNum && gfKind > 3.5) {
        // its three numerals inside the arc's ends and middle, about the needle's pivot low on the face
        vec3 gfVals = gfKind < 4.5 ? vec3(0.0, 1.0, 2.0) : gfKind < 5.5 ? vec3(0.0, 5.0, 10.0) :
                      gfKind < 6.5 ? vec3(40.0, 80.0, 120.0) : gfKind < 7.5 ? vec3(50.0, 100.0, 150.0) :
                      vec3(0.0, -1.0, 1.0);
        float gfSz = gfVals.z > 99.5 ? 0.17 : 0.2;
        for (int i = 0; i < 3; i++) {
          float v = gfVals[i];
          if (v < -0.5) continue;
          vec2 c = vec2(sin(radians(-48.0 + 48.0 * float(i))), cos(radians(-48.0 + 48.0 * float(i)))) * 0.52;
          c.y -= 0.14;
          gfNumInk = max(gfNumInk, gfNumber(gfP, c, v, gfSz, gfNe));
        }
      }
    }
    // the numerals finer than a pixel fade out
    gfNumInk *= kfade(0.1 * gfRad);
    gfInk = max(gfInk, gfNumInk);
    // the needle from just behind the hub out to the marks, tapering; a small gauge's pivots low, its needle long
    float gfAn = radians(-gfHalf + gfSw * gfReadAt);
    vec2 gfDir = vec2(sin(gfAn), cos(gfAn));
    vec2 gfQ = gfSmall ? gfP + vec2(0.0, 0.55) : gfP;
    float gfLen = gfSmall ? 1.3 : 0.8;
    float gfAlong = clamp(dot(gfQ, gfDir), -0.15, gfLen);
    float gfOff = length(gfQ - gfDir * gfAlong);
    float gfWide = 0.04 * (1.0 - 0.6 * max(gfAlong, 0.0) / gfLen);
    float gfNeedle = 1.0 - smoothstep(gfWide, gfWide + gfE, gfOff);
    gfNeedle *= step(length(gfP), 0.98);
    float gfHub = 1.0 - smoothstep(0.1, 0.1 + gfE, length(gfQ));
    gfHub *= step(length(gfP), 0.98);
    vec3 gfC = mix(p_gfFace, p_gfMark, clamp(gfInk, 0.0, 1.0));
    gfC = mix(gfC, p_gfRed, clamp(gfRedInk, 0.0, 1.0));
    gfC = mix(gfC, p_gfNeedle, gfNeedle);
    gfC = mix(gfC, vec3(0.02), gfHub);
    // finer than a pixel, the dial is the grey its marks make; and the bezel's shadow at its rim
    float gfF = kfade(0.1 * gfRad);
    gfC = mix(mix(p_gfFace, p_gfMark, 0.1), gfC, gfF);
    gfC *= 1.0 - 0.55 * smoothstep(0.9, 1.0, gfR);
    k.colour = gfC;
    k.metal = 0.0;
    k.rough = 0.5;
    k.glow = (p_gfMark * clamp(gfInk, 0.0, 1.0) + p_gfRed * clamp(gfRedInk, 0.0, 1.0) + p_gfNeedle * gfNeedle) * p_gfGlow * gfF * (1.0 - gfHub);
    }

}

void look_46(inout Look k) {
  p_cmGround = L46_cmGround;
  p_cmTitle = L46_cmTitle;
  p_cmInk = L46_cmInk;
  p_cmNeedle = L46_cmNeedle;
  p_cmRed = L46_cmRed;
  p_cmCell = L46_cmCell;
  p_cmRead1 = L46_cmRead1;
  p_cmRead2 = L46_cmRead2;
  p_cmRead3 = L46_cmRead3;
  p_cmTemp = L46_cmTemp;
  p_cmFan = L46_cmFan;
  p_cmFreq = L46_cmFreq;
  p_cmGain = L46_cmGain;
  p_cmRough = L46_cmRough;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    vec2 cmP, cmHalf;
    float cmPage;
    if (s2.x > 0.001 && s2.y > 0.001) {
      cmHalf = s2.xy * 0.5;
      cmP = s3 / cmHalf.y;
      cmPage = floor(s2.z + 0.5);
    } else {
      vec2 cmSize = vec2(p_cmCell * 1.75, p_cmCell);
      cmHalf = cmSize * 0.5;
      cmP = (fract(uv / cmSize) - 0.5) * 2.0 * vec2(1.75, 1.0);
      cmPage = 0.0;
    }
    if (cmPage > 3.5 || cmPage < -0.5) cmPage = 0.0;
    float cmA = cmHalf.x / cmHalf.y;
    float cmE = fwidth(cmP.y) * 0.9 + 0.002;
    float cmWhite = 0.0, cmAmber = 0.0, cmRedInk = 0.0;
    // the title strip across the top, its page's name in bars
    float cmTitleOn = step(0.72, cmP.y) * step(cmPage, 1.5);
    cmWhite = max(cmWhite, cmWord(cmP, -cmA + 0.1, 0.86, 4.0 + cmPage, 0.11, cmE) * cmTitleOn);
    // the screen's own window (the backlight's edge darkening a little at the rim)
    if (cmPage < 0.5) {
      for (int i = 0; i < 3; i++) {
        float cmX = (float(i) - 1.0) * cmA * 0.64;
        vec2 cmQ = (cmP - vec2(cmX, -0.02)) / 0.5;
        float cmR = length(cmQ);
        float cmEr = cmE / 0.5;
        float cmAng = degrees(atan(cmQ.x, cmQ.y));
        float cmFrom = cmAng + 135.0;
        float cmIn = step(-0.5, cmFrom) * step(cmFrom, 270.5);
        float cmStep = 270.0 / 20.0;
        float cmK = cmFrom / cmStep;
        float cmD = abs(fract(cmK + 0.5) - 0.5) * cmStep * 0.0174533 * cmR;
        float cmLong = step(abs(fract(cmK / 4.0 + 0.5) - 0.5) * 4.0, 0.5);
        float cmR0 = mix(0.78, 0.66, cmLong);
        float cmTick = (1.0 - smoothstep(0.035, 0.035 + cmEr, cmD)) * smoothstep(cmR0 - cmEr, cmR0, cmR) * (1.0 - smoothstep(0.92, 0.92 + cmEr, cmR)) * cmIn;
        float cmHot = step(270.0 * 0.8, cmFrom);
        cmWhite = max(cmWhite, cmTick * (1.0 - cmHot));
        cmRedInk = max(cmRedInk, cmTick * cmHot);
        // the scale's ring inside its ticks
        cmWhite = max(cmWhite, cmLine(cmR - 0.62, 0.012, cmEr) * cmIn * 0.6);
        float cmRead = i == 0 ? p_cmRead1 : i == 1 ? p_cmRead2 : p_cmRead3;
        float cmAn = radians(-135.0 + 270.0 * cmRead);
        vec2 cmDir = vec2(sin(cmAn), cos(cmAn));
        float cmAlong = clamp(dot(cmQ, cmDir), 0.0, 0.86);
        float cmOff = length(cmQ - cmDir * cmAlong);
        cmAmber = max(cmAmber, 1.0 - smoothstep(0.035, 0.035 + cmEr, cmOff));
        cmAmber = max(cmAmber, 1.0 - smoothstep(0.09, 0.09 + cmEr, cmR));
        // its reading under it, its name over it
        cmWhite = max(cmWhite, cmNumber(cmP, vec2(cmX, -0.48), cmRead * (i == 0 ? 1.0 : i == 1 ? 120.0 : 100.0), 3, i == 0 ? 2 : 0, 0.16, cmE));
        cmWhite = max(cmWhite, cmWord(cmP, cmX - 0.17, 0.52, 3.0, 0.07, cmE));
      }
    } else if (cmPage < 1.5) {
      vec2 cmG = vec2(cmP.x / (cmA - 0.1), (cmP.y + 0.05) / 0.72);
      float cmIn = step(abs(cmG.x), 1.0) * step(abs(cmG.y), 1.0);
      float cmGrid = max(cmLine(fract(cmG.x * 4.0 + 0.5) - 0.5, 0.01, cmE * 2.0), cmLine(fract(cmG.y * 2.0 + 0.5) - 0.5, 0.01, cmE * 2.0));
      cmWhite = max(cmWhite, cmGrid * cmIn * 0.25);
      float cmT1 = 0.55 * sin(cmG.x * 7.0 + 1.3) * exp(-0.4 * abs(cmG.x + 0.2)) + 0.1;
      float cmT2 = clamp(0.6 * sin(cmG.x * 4.0 - 0.5), -0.7, 0.8);
      cmAmber = max(cmAmber, cmLine(cmG.y - cmT1, 0.02, cmE * 1.6) * cmIn);
      cmWhite = max(cmWhite, cmLine(cmG.y - cmT2, 0.015, cmE * 1.6) * cmIn);
      for (int i = 0; i < 3; i++) {
        cmWhite = max(cmWhite, cmNumber(cmP, vec2(-cmA + 0.12, 0.62 - float(i) * 0.6), 2.0 - float(i), 1, 0, 0.1, cmE));
      }
    } else if (cmPage < 2.5) {
      cmWhite = max(cmWhite, cmNumber(cmP, vec2(-0.25, -0.05), p_cmTemp, 3, 1, 0.7, cmE));
      cmWhite = max(cmWhite, cmLine(length(cmP - vec2(0.42, 0.22)) - 0.06, 0.018, cmE));
      for (int i = 0; i < 7; i++) {
        float x = 0.75 + float(i) * 0.1;
        float hgt = 0.12 + float(i) * 0.06;
        float lit = step(float(i) + 0.5, p_cmFan);
        float bar = cmBox(cmP, vec2(x, -0.5), vec2(x + 0.06, -0.5 + hgt), cmE);
        cmWhite = max(cmWhite, bar * mix(0.15, 1.0, lit));
      }
      cmAmber = max(cmAmber, cmBox(cmP, vec2(0.75, 0.3), vec2(1.2, 0.45), cmE));
    } else {
      cmAmber = max(cmAmber, cmWord(cmP, -cmA + 0.15, 0.35, 2.0, 0.16, cmE));
      cmWhite = max(cmWhite, cmNumber(cmP, vec2(0.0, -0.1), p_cmFreq, 4, 1, 0.66, cmE));
      vec2 cmBx = vec2(cmA - 0.32, -0.1);
      float cmFrame = cmBox(cmP, cmBx - 0.18, cmBx + 0.18, cmE) * (1.0 - cmBox(cmP, cmBx - 0.15, cmBx + 0.15, cmE));
      cmWhite = max(cmWhite, max(cmFrame, cmNumber(cmP, cmBx, 3.0, 1, 0, 0.22, cmE)));
    }
    // finer than a pixel, the figures fade to the page's mean glow: each page by its finest stroke (the meters' ticks, the
    // graph's traces, the big figures' segments), in the screen's half heights
    float cmStroke = cmPage < 0.5 ? 0.035 : cmPage < 1.5 ? 0.03 : 0.11;
    // the readouts (climate, radio) drawn harder: a darker ground, brighter figures
    bool cmReadout = cmPage > 1.5;
    float cmF = 1.0 - smoothstep(cmStroke * 0.6, cmStroke * 1.6, fwidth(cmP.y));
    cmWhite = clamp(cmWhite, 0.0, 1.0) * cmF;
    cmAmber = clamp(cmAmber, 0.0, 1.0) * cmF;
    cmRedInk = clamp(cmRedInk, 0.0, 1.0) * cmF;
    float cmMean = 0.035 * (1.0 - cmF);
    vec3 cmBack = mix(p_cmGround, p_cmTitle, cmTitleOn);
    // the backlight's edge: a little darker toward the rim
    float cmEdge = 1.0 - 0.35 * smoothstep(0.75, 1.0, max(abs(cmP.x) / cmA, abs(cmP.y)));
    if (cmReadout) {
      cmBack *= 0.45;
      cmWhite *= 1.6;
      cmAmber *= 1.4;
      cmMean *= 0.8;
    }
    vec3 cmLit = cmBack * cmEdge + p_cmInk * cmWhite + p_cmNeedle * cmAmber + p_cmRed * cmRedInk + p_cmInk * cmMean;
    k.colour = cmLit * 0.15;
    k.metal = 0.0;
    k.rough = p_cmRough;
    k.glow = p_cmGain * cmLit;
    k.clearcoat = 0.8;
    k.clearcoatRough = 0.05;

}

void look_47(inout Look k) {
  p_glTint = L47_glTint;
  p_glTint2 = L47_glTint2;
  p_glWaves = L47_glWaves;
  p_glWaveDepth = L47_glWaveDepth;
  p_glSeeds = L47_glSeeds;
  p_glRough = L47_glRough;
  p_glAlpha = L47_glAlpha;
  p_glAlphaVar = L47_glAlphaVar;
  p_glRibs = L47_glRibs;
  p_glRibWide = L47_glRibWide;
  p_glRibAlpha = L47_glRibAlpha;
  p_glGlow = L47_glGlow;
  p_glCrease = L47_glCrease;
  p_glCreaseFreq = L47_glCreaseFreq;
  p_glBands = L47_glBands;
  p_glBandHigh = L47_glBandHigh;
  vec2 uv = vLookUv;
  float seed = vLookInfo.y * 7.13 + vLookInfo.z * 1.71;
  vec3 wp = vLookWorld;
  vec3 wn = normalize(vLookWN);

    float wave = kfbm4(uv * p_glWaves + seed);
    float seeds = smoothstep(0.08, 0.02, kcell(uv * 60.0 + seed)) * kfade(0.01);
    // the twin wall's ribs, along u, one every 1 / glRibs metres across v; under a pixel, their mean cover
    float glRib = 0.0;
    if (p_glRibs > 0.0) {
      float glRd = abs(fract(uv.y * p_glRibs) - 0.5) * 2.0;
      float glRw = fwidth(uv.y * p_glRibs) * 2.0;
      float glLine = 1.0 - smoothstep(p_glRibWide - glRw, p_glRibWide + glRw, 1.0 - glRd);
      glRib = mix(p_glRibWide, glLine, kfade(1.5 / p_glRibs));
    }
    // the film's creases and wound bands, level round the load (the world's height, and the way along the face)
    float glFold = 0.0, glBand = 0.0;
    if (p_glCrease > 0.0 || p_glBands > 0.0) {
      vec3 glSide = cross(vec3(0.0, 1.0, 0.0), wn);
      float glAlong = dot(glSide, glSide) > 0.01 ? dot(wp, normalize(glSide)) : wp.x;
      float glUp = wp.y + 0.03 * kn(vec2(glAlong * 2.0, 0.0) + seed);
      float glF = kn(vec2(glAlong * 1.6, glUp * p_glCreaseFreq) + seed * 1.7);
      float glF2 = kn(vec2(glAlong * 3.1, glUp * p_glCreaseFreq * 2.3) + seed + 5.0);
      glFold = p_glCrease * mix(0.35, pow(1.0 - abs(glF * 2.0 - 1.0), 6.0) * 0.75 + pow(1.0 - abs(glF2 * 2.0 - 1.0), 8.0) * 0.4,
                                kfade(1.0 / p_glCreaseFreq));
      float glB = fract(glUp / p_glBandHigh + 0.15 * kn(vec2(glAlong * 0.8, 3.0) + seed));
      glBand = p_glBands * smoothstep(0.55, 0.62, glB) * (0.8 + 0.4 * kn(vec2(glAlong * 4.0, glUp * 6.0) + seed));
    }
    k.colour = mix(p_glTint, p_glTint2, wave) + seeds * p_glSeeds + vec3(0.12 * glRib + 0.25 * glFold + 0.06 * glBand);
    k.rough = p_glRough + p_glRough * wave;
    k.metal = 0.0;
    k.height = p_glWaveDepth * (wave - 0.5) + 0.0003 * glFold;
    k.alpha = clamp(p_glAlpha + p_glAlphaVar * wave + p_glRibAlpha * glRib + 0.35 * glFold + 0.18 * glBand, 0.0, 1.0);
    k.glow = p_glGlow * (0.9 + 0.2 * wave) * (1.0 + 0.4 * glRib);

}

void look_48(inout Look k) {
  p_plColour = L48_plColour;
  p_plStipple = L48_plStipple;
  p_plRelief = L48_plRelief;
