void look_50(inout Look k) {
  p_clColour = L50_clColour;
  p_clRub = L50_clRub;
  p_clGrain = L50_clGrain;
  p_clGrainDepth = L50_clGrainDepth;
  p_clCreases = L50_clCreases;
  p_clCrease = L50_clCrease;
  p_clWear = L50_clWear;
